1: // 真实后端请求封装：注入 zhi-project-id 头、Bearer token、解包 {code,msg,data}
2: export interface RequestOptions {
3:   method?: 'GET' | 'POST' | 'PUT' | 'DELETE'
4:   data?: unknown
5:   token?: string | false
6:   projectId?: string
7:   raw?: boolean
8:   baseUrl?: string
9:   /** 额外请求头（如查询用户信息时 苏住房C 传入 zs-desensitize-flag: 0） */
10:   headers?: Record<string, string>
11: }
12: export interface TransportInput {
13:   url: string
14:   method: NonNullable<RequestOptions['method']>
15:   data?: unknown
16:   header: Record<string, string>
17:   timeout: number
18: }
19: export type Transport = (input: TransportInput) => Promise<{ statusCode: number; data: unknown }>
20: export interface Envelope<T> { code: number; msg: string; data: T }
21: export interface RequestConfig { baseUrl: string | (() => string); projectId: string | (() => string); getToken?: () => string | undefined }
22: 
23: function resolveConfigValue(value: string | (() => string)): string {
24:   return typeof value === 'function' ? value() : value
25: }
26: 
27: // 兼容旧签名：createRequest(transport, baseUrlString) -> 纯透传旧行为
28: // 新签名：createRequest(transport, configObject) -> 注入头 + 解包
29: export function createRequest(transport: Transport, baseUrlOrConfig: string | RequestConfig) {
30:   const legacy = typeof baseUrlOrConfig === 'string'
31:   const config: RequestConfig = legacy ? { baseUrl: baseUrlOrConfig, projectId: 'suzhufang' } : baseUrlOrConfig
32:   return async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
33:     const baseUrl = options.baseUrl ?? resolveConfigValue(config.baseUrl)
34:     if (!baseUrl) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL（推荐 /api）')
35:     const header: Record<string, string> = { 'Content-Type': 'application/json', ...(options.headers ?? {}) }
36:     if (!legacy) {
37:       const useToken = options.token === false ? undefined : (options.token || config.getToken?.())
38:       header['zhi-project-id'] = options.projectId ?? resolveConfigValue(config.projectId)
39:       if (useToken) header.Authorization = `Bearer ${useToken}`
40:     } else if (options.token) {
41:       header.Authorization = `Bearer ${options.token}`
42:     }
43:     const response = await transport({
44:       url: `${baseUrl.replace(/\/$/, '')}/${path.replace(/^\//, '')}`,
45:       method: options.method ?? 'GET',
46:       data: options.data,
47:       header,
48:       timeout: 20000,
49:     })
50:     if (response.statusCode < 200 || response.statusCode >= 300) {
51:       const body = response.data as Envelope<unknown> | undefined
52:       const msg = body && typeof body === 'object' && 'msg' in body ? String(body.msg) : ''
53:       throw new Error(msg || `请求失败（HTTP ${response.statusCode}）`)
54:     }
55:     if (legacy || options.raw) return response.data as T
56:     const body = response.data as Envelope<T>
57:     if (body && typeof body === 'object' && 'code' in body) {
58:       if (body.code !== 200) throw new Error(body.msg || `业务异常（code ${body.code}）`)
59:       return body.data
60:     }
61:     return response.data as T
62:   }
63: }
64: 
65: export const uniTransport: Transport = input => new Promise((resolve, reject) => {
66:   uni.request({
67:     url: input.url,
68:     method: input.method as never,
69:     data: input.data as Record<string, unknown> | undefined,
70:     header: input.header,
71:     timeout: input.timeout,
72:     success: result => resolve({ statusCode: result.statusCode, data: result.data }),
73:     fail: result => reject(new Error(result.errMsg?.includes('timeout') ? '请求超时，请重试' : '网络连接失败，请重试')),
74:   })
75: })
