77: const TOKEN_KEY = 'flood-token-v1'
78: export function getToken(): string | undefined {
79:   try { const t = uni.getStorageSync(TOKEN_KEY); return typeof t === 'string' && t ? t : undefined } catch { return undefined }
80: }
81: export function setToken(token: string) { try { uni.setStorageSync(TOKEN_KEY, token) } catch { /* ignore */ } }
82: export function clearToken() { try { uni.removeStorageSync(TOKEN_KEY) } catch { /* ignore */ } }
