102: }
103: 
104: /** 网关图形验证码：GET /v2.0/code（与 main 分支 getCodeImg → /api/v2.0/code 一致） */
105: export interface LoginCaptchaPayload {
106:   enabled: boolean
107:   uuid?: string
108:   imageDataUrl?: string
109: }
110: 
111: export async function fetchLoginCaptcha(): Promise<LoginCaptchaPayload> {
112:   // 图形验证码仅暴露于后端网关，demo 模式下也走同源 /api 反代（nginx 已代理 /api → 网关）。
113:   const apiBase = getApiBase() || '/api'
114:   const url = `${apiBase.replace(/\/$/, '')}/v2.0/code`
115:   const response = await uniTransport({
116:     url,
117:     method: 'GET',
118:     header: { Accept: 'application/json, text/plain, */*', 'zhi-project-id': getProjectId() },
119:     timeout: 20000,
120:   })
121:   if (response.statusCode < 200 || response.statusCode >= 300) {
122:     throw new Error(`验证码加载失败（HTTP ${response.statusCode}）`)
123:   }
124:   const body = response.data as {
125:     code?: number
126:     msg?: string
127:     captchaOnOff?: boolean
128:     uuid?: string
129:     data?: string
130:   } | null
131:   if (body && typeof body === 'object' && 'code' in body && body.code !== 200) {
132:     throw new Error(body.msg || '验证码加载失败')
133:   }
134:   const enabled = body?.captchaOnOff !== false && Boolean(body?.uuid && body?.data)
135:   if (!enabled) return { enabled: false }
136:   const raw = String(body!.data)
137:   const imageDataUrl = raw.startsWith('data:') ? raw : `data:image/jpeg;base64,${raw}`
138:   return { enabled: true, uuid: String(body!.uuid), imageDataUrl }
139: }
140: // 统一网关前缀（/api + /v2.0/...，对齐 main 分支 request 封装）
141: export const request = createRequest(uniTransport, {
142:   baseUrl: getApiBase,
143:   projectId: getProjectId,
144:   getToken,
145: })
146: /** @deprecated 与 request 同源，保留别名避免旧引用报错 */
147: export const authRequest = request
