149: /**
150:  * H5 带鉴权下载文件流（PDF 等）。
151:  * window.open 直接导航不会携带 Authorization 头，后端会返回 401「令牌不能为空」；
152:  * 这里用原生 fetch 手动注入 Bearer + zhi-project-id，拿到 blob 后用临时 <a download> 触发下载。
153:  */
154: export async function downloadFileWithAuth(path: string, filename: string): Promise<void> {
155:   const apiBase = getApiBase()
156:   if (!apiBase) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL')
157:   const url = `${apiBase.replace(/\/$/, '')}/${path.replace(/^\//, '')}`
158:   const headers: Record<string, string> = { 'zhi-project-id': getProjectId() }
159:   const token = getToken()
160:   if (token) headers.Authorization = `Bearer ${token}`
161:   const resp = await fetch(url, { headers })
162:   if (!resp.ok) {
163:     let msg = `下载失败（HTTP ${resp.status}）`
164:     try { const j = await resp.json(); if (j && j.msg) msg = String(j.msg) } catch { /* 非 JSON 错误体，保留默认文案 */ }
165:     throw new Error(msg)
166:   }
167:   const blob = await resp.blob()
168:   const objectUrl = URL.createObjectURL(blob)
169:   const a = document.createElement('a')
170:   a.href = objectUrl
171:   a.download = filename
172:   document.body.appendChild(a)
173:   a.click()
174:   a.remove()
175:   setTimeout(() => URL.revokeObjectURL(objectUrl), 1500)
176: }

