/**
 * 富文本正文规范化（H5 `rich-text` 渲染前置处理）。
 *
 * 背景：文章 / 公告 / 消息详情接口返回的正文是 HTML，图片 src 是文件服务相对路径
 * （如 /zhi2-pro/2026/x/l/p/xxx.png）。门户 H5 站点没有反代 /zhi2-pro，直接把这段
 * HTML 交给 rich-text 会让图片全部 404，正文看起来完全空白。
 *
 * 处理内容：
 * - 把文件服务相对路径补成完整 URL（域名可用 VITE_MEDIA_BASE_URL 覆盖，置空表示站点已有反代）；
 * - 解码 HTML 实体、纯文本换行转 <br/>、转义非法尖括号（书名号等会导致 rich-text 白屏）；
 * - 给 <img> 加内联最大宽度约束，避免长图溢出屏幕。
 */
const DEFAULT_MEDIA_BASE = 'https://szfweb.szzfcjj.cn:8887'
const SERVER_MEDIA_PREFIXES = ['/zhi2-pro', '/zhi2-dev', '/zhi2-test', '/zs-fym', '/zhl2-pro']

type EnvRecord = Record<string, string | undefined>

function mediaBase(): string {
  const env = (import.meta as unknown as { env?: EnvRecord }).env ?? {}
  const configured = env.VITE_MEDIA_BASE_URL
  // 显式配置为空：站点自带文件服务反向代理，保持相对路径
  if (configured === '') return ''
  return String(configured || DEFAULT_MEDIA_BASE).replace(/\/+$/, '')
}

/** 把接口返回的相对媒体地址转成 rich-text 可直接加载的 URL */
export function resolveServerMediaUrl(raw: unknown): string {
  const url = String(raw ?? '').trim()
  if (!url) return ''
  if (/^(data:|blob:|https?:\/\/)/i.test(url)) return url
  // 项目内静态资源不走文件服务
  if (/^\/?(?:static|images|svg)\//i.test(url)) return url.startsWith('/') ? url : `/${url}`
  const path = url.startsWith('/') ? url : `/${url}`
  const isServerMedia = SERVER_MEDIA_PREFIXES.some(prefix => path.toLowerCase().startsWith(prefix))
  if (!isServerMedia) return path
  const base = mediaBase()
  return base ? `${base}${path}` : path
}

const RICH_TEXT_FIELD_KEYS = ['configValue', 'content', 'msgContent', 'noticeContent', 'value']

function normalizeInput(value: unknown): string {
  if (value == null || value === '') return ''
  if (typeof value === 'string') return value
  if (typeof value === 'object') {
    const row = value as Record<string, unknown>
    for (const key of RICH_TEXT_FIELD_KEYS) {
      const field = row[key]
      if (field != null && field !== '') return String(field)
    }
  }
  return String(value)
}

function decodeHtmlEntities(text: string): string {
  let result = text
  let prev = ''
  let count = 0
  while (result !== prev && count < 3) {
    prev = result
    result = result
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&nbsp;/g, '\u00A0')
    count += 1
  }
  return result
}

function plainTextToHtml(text: string): string {
  return /<[a-z][\s\S]*?>/i.test(text) ? text : text.replace(/\n/g, '<br/>')
}

/** 转义非 HTML 标签中的 <，避免书名号等内容被误解析为标签导致 rich-text 白屏 */
function escapeInvalidAngleBrackets(html: string): string {
  return html.replace(/<(?!\/?[a-zA-Z!])/g, '&lt;')
}

const IMG_SRC_RE = /(<img\b[^>]*?\ssrc\s*=\s*)(?:"([^"]*)"|'([^']*)'|([^\s>]+))/gi

function formatImgTag(tag: string): string {
  const withSrc = tag.replace(IMG_SRC_RE, (_match, prefix: string, dquote?: string, squote?: string, unquoted?: string) => {
    const src = dquote ?? squote ?? unquoted ?? ''
    const resolved = resolveServerMediaUrl(src)
    if (dquote !== undefined) return `${prefix}"${resolved}"`
    if (squote !== undefined) return `${prefix}'${resolved}'`
    return `${prefix}${resolved}`
  })
  const styleRe = /\sstyle\s*=\s*(?:"([^"]*)"|'([^']*)')/i
  const styleMatch = withSrc.match(styleRe)
  const existing = (styleMatch?.[1] ?? styleMatch?.[2] ?? '').trim().replace(/;+$/, '')
  // scoped CSS 作用不到 rich-text 内部节点，宽度约束必须内联
  const style = `${existing ? `${existing};` : ''}max-width:100%;height:auto`
  if (styleMatch) return withSrc.replace(styleRe, ` style="${style}"`)
  return withSrc.replace(/^<img\b/i, `<img style="${style}"`)
}

function replaceCssUrls(html: string): string {
  return html.replace(/url\((['"]?)([^'")]+)\1\)/gi, (match, quote: string, url: string) => {
    const trimmed = url.trim()
    const resolved = resolveServerMediaUrl(trimmed)
    return resolved === trimmed ? match : `url(${quote}${resolved}${quote})`
  })
}

/** 将接口返回值规范为 rich-text 可渲染的 HTML */
export function formatRichTextContent(content: unknown): string {
  const html = escapeInvalidAngleBrackets(plainTextToHtml(decodeHtmlEntities(normalizeInput(content))))
  if (!html) return html
  return replaceCssUrls(html.replace(/<img\b[^>]*>/gi, tag => formatImgTag(tag)))
}

