import { describe, expect, it } from 'vitest'
import { formatRichTextContent, resolveServerMediaUrl } from '../src/utils/richText'
import { resolveMedia } from '../src/utils/portalData'

const BASE = 'https://szfweb.szzfcjj.cn:8887'
const IMG = '/zhi2-pro/2026/x/l/p/0ef562f5-3873-406f-9147-5dbed075d626.png'

describe('resolveServerMediaUrl', () => {
  it('文件服务相对路径补成完整 URL', () => {
    expect(resolveServerMediaUrl(IMG)).toBe(`${BASE}${IMG}`)
    expect(resolveServerMediaUrl(IMG.slice(1))).toBe(`${BASE}${IMG}`)
    expect(resolveServerMediaUrl('/zs-fym/2026/a.jpg')).toBe(`${BASE}/zs-fym/2026/a.jpg`)
  })

  it('绝对 URL / data URI / 本地静态资源保持原样', () => {
    expect(resolveServerMediaUrl('https://cdn.example.com/a.png')).toBe('https://cdn.example.com/a.png')
    expect(resolveServerMediaUrl('data:image/png;base64,AAAA')).toBe('data:image/png;base64,AAAA')
    expect(resolveServerMediaUrl('/static/logo.png')).toBe('/static/logo.png')
    expect(resolveServerMediaUrl('/other/a.png')).toBe('/other/a.png')
    expect(resolveServerMediaUrl('')).toBe('')
  })
})

describe('formatRichTextContent', () => {
  it('正文图片补全域名并加内联宽度约束', () => {
    const out = formatRichTextContent(`<p><img src="${IMG}" alt="" data-href="" style=""/></p>`)
    expect(out).toContain(`src="${BASE}${IMG}"`)
    expect(out).toContain('max-width:100%;height:auto')
  })

  it('多张图片与单引号 src 都能处理，完整 URL 不重复拼接', () => {
    const html = `<p><img src='${IMG}'/><img src="https://cdn.example.com/b.png"/></p>`
    const out = formatRichTextContent(html)
    expect(out).toContain(`src='${BASE}${IMG}'`)
    expect(out).toContain('src="https://cdn.example.com/b.png"')
    expect(out).not.toContain(`${BASE}https://`)
  })

  it('CSS 背景图同样补全域名', () => {
    expect(formatRichTextContent(`<div style="background:url(${IMG})"></div>`))
      .toContain(`url(${BASE}${IMG})`)
  })

  it('解码 HTML 实体、转义非法尖括号、纯文本换行转 br', () => {
    expect(formatRichTextContent('&lt;p&gt;台风避险指南&lt;/p&gt;')).toBe('<p>台风避险指南</p>')
    expect(formatRichTextContent('风力3<5级')).toBe('风力3&lt;5级')
    expect(formatRichTextContent('第一行\n第二行')).toBe('第一行<br/>第二行')
  })

  it('兼容对象形式的接口返回值', () => {
    expect(formatRichTextContent({ configValue: `<img src="${IMG}"/>` })).toContain(`${BASE}${IMG}`)
    expect(formatRichTextContent({ content: '正文' })).toBe('正文')
    expect(formatRichTextContent('')).toBe('')
  })
})

describe('portal resolveMedia', () => {
  it('列表封面与头像不再丢弃文件服务相对路径', () => {
    expect(resolveMedia(IMG)).toBe(`${BASE}${IMG}`)
    expect(resolveMedia('/static/banner.png')).toBe('/static/banner.png')
  })
})

